h1 {
  color: rebeccapurple;                 /* a named colour */
}

.card {
  color: #3730a3;                       /* hex */
  background-color: #eef2ff;
  border: 2px solid currentColor;       /* same as the text colour */
  padding: 1rem;
}

button {
  background-color: hsl(243 75% 59%);   /* hsl: hue, saturation, lightness */
  color: white;
  border: none;
  padding: 0.5rem 1rem;
}

h1 {
  color: hsl(220 80% 30%);            /* dark */
}

a {
  color: hsl(220 80% 45%);            /* medium */
}

.card {
  background-color: hsl(220 80% 96%); /* very light */
  border: 1px solid hsl(220 80% 85%);
  padding: 1rem;
}

button {
  background-color: rgb(29 78 216);
  color: rgb(255 255 255);
  border: none;
  padding: 0.5rem 1rem;
}

body {
  background-color: #1e3a8a;
  color: white;
}

/* Translucent background, solid text */
.card {
  background-color: rgb(255 255 255 / 15%);
  padding: 1rem;
}

/* Everything inside fades, including the label */
button {
  opacity: 0.5;
}
